def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0))

    prev_bids = []
    cindy_bid = None
    eric_bid = None
    for opp_id, opp in opponents_status.items():
        if not opp.get('alive'):
            continue
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if opp_id == 'Cindy':
                cindy_bid = float(bid)
            if opp_id == 'Eric':
                eric_bid = float(bid)

    if eric_bid is None:
        eric_bid = 15.0

    tight_supply = supply <= 17
    very_tight_supply = supply <= 15

    danger = False
    if hp <= 3 or no_water >= 2:
        danger = True

    severe_danger = False
    if hp <= 2 or no_water >= 3:
        severe_danger = True

    if severe_danger:
        target = 96.0
        if cindy_bid is not None:
            target = max(target, cindy_bid + 2.0)
        return float(min(budget, target))

    if danger:
        if tight_supply:
            target = 92.0
            if cindy_bid is not None:
                target = max(target, cindy_bid + 1.0)
            return float(min(budget, target))
        return float(min(budget, max(28.0, eric_bid + 3.0)))

    if very_tight_supply:
        target = 88.0
        if cindy_bid is not None and cindy_bid < 110.0:
            target = max(target, cindy_bid + 1.0)
        return float(min(budget, target))

    if tight_supply:
        return float(min(budget, max(22.0, eric_bid + 2.5)))

    if cindy_bid is not None and cindy_bid >= 90.0:
        return float(min(budget, max(16.5, eric_bid + 1.0)))

    if prev_bids:
        highest_prev = max(prev_bids)
        target = min(highest_prev + 1.0, 30.0)
        target = max(target, eric_bid + 1.0, 16.0)
        return float(min(budget, target))

    return float(min(budget, 17.0))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']

    # collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in opponents_status.values():
        if opp['alive']:
            prev = opp.get('previous_trace', {})
            if prev and 'bid' in prev and prev['bid'] is not None:
                yesterday_bids.append(prev['bid'])

    high_bid = max(yesterday_bids) if yesterday_bids else 0

    # supply-based aggressiveness
    if supply <= 18:
        target_bid = max(high_bid + 1, DAILY_SALARY * 0.7)
    elif supply >= 22:
        target_bid = min(DAILY_SALARY * 0.4, high_bid - 5 if high_bid > 0 else DAILY_SALARY * 0.3)
    else:
        if hp <= 3:
            target_bid = max(high_bid + 1, DAILY_SALARY * 0.6)
        else:
            target_bid = min(DAILY_SALARY * 0.5, high_bid - 2 if high_bid > 0 else DAILY_SALARY * 0.4)

    bid = min(budget, max(0, target_bid))
    return round(bid, 2)
